    </div>

    <div v-else class="favorites__grid">
      <div
        v-for="product in favorites"
        :key="product.id"
        class="favorites__card"
        @click="router.push(`/product/${product.id}`)"
      >
        <button class="favorites__card-like" @click.stop="removeFavorite(product.id)">
          <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
            <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"
              fill="#00C27C" stroke="#00C27C" stroke-width="1.5"/>
          </svg>
        </button>

        <div class="favorites__card-img">
          <img :src="product.image" :alt="product.name" />
        </div>

        <div class="favorites__card-info">
          <p class="favorites__card-name">{{ product.name }}</p>
          <span class="favorites__card-price">{{ product.price.toLocaleString() }} ₸</span>
          <div class="favorites__card-location">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none">
              <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" fill="#848484"/>
            </svg>
            <span>{{ product.location }}</span>
          </div>
        </div>
      </div>
    </div>

    <!-- Кнопка только когда есть товары -->
    <div v-if="favorites.length > 0" class="favorites__cta-wrap">
      <button class="favorites__cta" @click="navigate('my-help')">
        Перейти к покупкам
      </button>
    </div>

    <!-- Навбар всегда -->
    <div class="favorites__nav">
      <button
        v-for="tab in tabs"
        :key="tab.id"
        class="favorites__nav-btn"
        :class="{ active: tab.id === 'favorites' }"
        @click="navigate(tab.id)"
      >
        <span v-html="tab.icon" />
        <span>{{ tab.name }}</span>
      </button>
    </div>
  </div>
</template>

<script setup>
import { useRouter } from 'vue-router'
import { ref, onMounted } from 'vue'
import { useFavourites } from '../composables/useFavourites'


const favorites = ref([])
const router = useRouter()
const goToNotifications = () => {
  router.push('/notifications')
}
onMounted(() => {
  favorites.value = JSON.parse(localStorage.getItem('favorites') || '[]')
})

function navigate(tabId) {
  const routes = {
    catalogue: '/catalogue',
    favorites: '/favorites',
    funds: '/funds',
    purchases: '/purchases',
    profile: '/profile',
    'my-help': '/my-help'
  }
  if (routes[tabId]) router.push(routes[tabId])
}

function removeFavorite(id) {
  favorites.value = favorites.value.filter(f => f.id !== id)
  localStorage.setItem('favorites', JSON.stringify(favorites.value))
}

const tabs = [
